import { describe, it, expect } from 'vitest';
import { createHash } from 'node:crypto';
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative, resolve, sep } from 'node:path';

/**
 * SPECIALISTS-4344. The Claude Code plugin carries a byte-identical copy of the
 * canonical using-specialists skill because a marketplace install copies only
 * the plugin folder and cannot run the package build. The copy is generated by
 * scripts/sync-plugin-skill.mjs and committed — this test pins the equality so
 * either side drifting goes red, and proves the retired
 * supervising-activations skill is gone.
 */

const REPO = resolve(__dirname, '../../..');
const CANONICAL = join(REPO, 'config', 'skills', 'using-specialists');
const PLUGIN_COPY = join(REPO, 'plugins', 'specialists', 'skills', 'using-specialists');
const RETIRED = join(REPO, 'plugins', 'specialists', 'skills', 'supervising-activations');

function skillFiles(dir: string, base: string = dir): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      if (relative(base, full).split(sep).includes('evals')) return [];
      return skillFiles(full, base);
    }
    return entry.isFile() ? [full] : [];
  });
}

function snapshot(dir: string): Map<string, string> {
  const map = new Map<string, string>();
  for (const file of skillFiles(dir)) {
    const rel = relative(dir, file).split(sep).join('/');
    map.set(rel, createHash('sha256').update(readFileSync(file)).digest('hex'));
  }
  return map;
}

describe('plugin skill parity: committed copy is byte-identical to the canonical skill', () => {
  it('retires supervising-activations from the plugin', () => {
    expect(existsSync(RETIRED), 'retired plugin skill still present').toBe(false);
  });

  it('ships the same relative paths on both sides (evals excluded by package contract)', () => {
    const canonical = [...snapshot(CANONICAL).keys()].sort();
    const copy = [...snapshot(PLUGIN_COPY).keys()].sort();
    expect(copy, 'plugin copy missing or has extra files').toEqual(canonical);
    expect(copy.length).toBeGreaterThan(0);
  });

  it('matches byte-for-byte, so a deliberate edit of either side fails', () => {
    const canonical = snapshot(CANONICAL);
    const copy = snapshot(PLUGIN_COPY);
    const mismatched: string[] = [];
    for (const [rel, hash] of canonical) {
      if (copy.get(rel) !== hash) mismatched.push(rel);
    }
    expect(mismatched, `run: node scripts/sync-plugin-skill.mjs — ${mismatched.join(', ')}`).toEqual([]);
  });

  it('keeps the canonical frontmatter name both runtimes address', () => {
    const root = readFileSync(join(PLUGIN_COPY, 'SKILL.md'), 'utf8');
    expect(root).toContain('name: using-specialists');
    expect(statSync(join(PLUGIN_COPY, 'references', 'claude-code.md')).size).toBeGreaterThan(0);
  });
});
